9	public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
10	{
11	    public DbSet<Venue> Venues => Set<Venue>();
12	    public DbSet<Room> Rooms => Set<Room>();
13	    public DbSet<Event> Events => Set<Event>();
14	    public DbSet<PriceCategory> PriceCategories => Set<PriceCategory>();
15	    public DbSet<Booking> Bookings => Set<Booking>();
16	    public DbSet<BookingPosition> BookingPositions => Set<BookingPosition>();
17	
18	    protected override void OnModelCreating(ModelBuilder modelBuilder)
19	    {
20	        modelBuilder.Entity<Venue>(entity =>
21	        {
22	            entity.HasMany(v => v.Rooms)
23	                .WithOne()
24	                .HasForeignKey(r => r.VenueId)
25	                .OnDelete(DeleteBehavior.Restrict);
26	        });
27	
28	        modelBuilder.Entity<Room>(entity =>
29	        {
30	            entity.HasMany(r => r.Events)
31	                .WithOne()
32	                .HasForeignKey(e => e.RoomId)
33	                .OnDelete(DeleteBehavior.Restrict);
34	
35	            ConfigureJsonListConversion<IReadOnlyList<string>, string>(entity.Property(r => r.RowLabels));
36	            ConfigureJsonListConversion<IReadOnlyCollection<int>, int>(entity.Property(r => r.AisleColumns));
37	        });
38	
39	        modelBuilder.Entity<Event>(entity =>
40	        {
41	            entity.HasMany(e => e.PriceCategories)
42	                .WithOne()
43	                .HasForeignKey(pc => pc.EventId)
44	                .OnDelete(DeleteBehavior.Restrict);
45	
46	            entity.HasMany(e => e.BookingPositions)
47	                .WithOne()
48	                .HasForeignKey(bp => bp.EventId)
49	                .OnDelete(DeleteBehavior.Restrict);
50	        });
51	
52	        modelBuilder.Entity<PriceCategory>(entity =>
53	        {
54	            entity.Property(pc => pc.Preis).HasPrecision(10, 2);
55	        });
56	
57	        modelBuilder.Entity<Booking>(entity =>
58	        {
59	            entity.Property(b => b.Reference)
60	                .HasMaxLength(8)
61	                .IsRequired()
62	                .UseCollation("SQL_Latin1_General_CP1_CI_AS");
63	            entity.HasIndex(b => b.Reference).IsUnique();
64	
65	            entity.HasMany(b => b.Positions)
66	                .WithOne()
67	                .HasForeignKey(bp => bp.BookingId)
68	                .OnDelete(DeleteBehavior.Restrict);
69	        });
70	
71	        modelBuilder.Entity<BookingPosition>(entity =>
72	        {
73	            entity.HasOne<PriceCategory>()
74	                .WithMany()
75	                .HasForeignKey(bp => bp.PriceCategoryId)
76	                .OnDelete(DeleteBehavior.Restrict);
77	
78	            entity.HasIndex(bp => new { bp.EventId, bp.RowLabel, bp.ColumnNumber })
79	                .IsUnique()
80	                .HasFilter("[CancelledAtUtc] IS NULL");
81	
82	            entity.ToTable(t => t.HasCheckConstraint(
83	                "CK_BookingPositions_BookingId_PriceCategoryId_BeideNullOderBeideGesetzt",
84	                "([BookingId] IS NULL AND [PriceCategoryId] IS NULL) OR ([BookingId] IS NOT NULL AND [PriceCategoryId] IS NOT NULL)"));
85	        });
86	    }
87	
88	    /// <summary>
89	    /// Persistiert eine Listen-Property als JSON-String mit einem korrekten Value-Comparer für
90	    /// EF-Core-Change-Tracking. Gemeinsame Konfiguration für `Room.RowLabels`/`Room.AisleColumns`,
91	    /// die sich zuvor nur im Element-/Property-Typ unterschied.
92	    /// </summary>
93	    private static void ConfigureJsonListConversion<TCollection, TItem>(PropertyBuilder<TCollection> property)
94	        where TCollection : class, IReadOnlyCollection<TItem>
95	    {
96	        property
97	            .HasConversion(
98	                v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
99	                v => (TCollection)(object)(JsonSerializer.Deserialize<List<TItem>>(v, JsonSerializerOptions.Default) ?? new List<TItem>()))
100	            .Metadata.SetValueComparer(new ValueComparer<TCollection>(
101	                (a, b) => (a ?? (TCollection)(object)new List<TItem>()).SequenceEqual(b ?? (TCollection)(object)new List<TItem>()),
102	                v => (v ?? (TCollection)(object)new List<TItem>()).Aggregate(0, (hash, item) => HashCode.Combine(hash, item)),
103	                v => (TCollection)(object)((IEnumerable<TItem>)(v ?? (TCollection)(object)new List<TItem>())).ToList()));
104	    }
105	}
