9	/// und `PriceCategoryId` immer gemeinsam null oder gemeinsam gesetzt sind (AD-2), statt sie nur
10	/// über einen XML-Doc-Kommentar zu dokumentieren.
11	/// </summary>
12	public class BookingPositionInvariantTests : IAsyncLifetime
13	{
14	    private readonly SqlServerTestDatabase _database = new();
15	
16	    public ValueTask InitializeAsync() => _database.InitializeAsync();
17	
18	    public ValueTask DisposeAsync() => _database.DisposeAsync();
19	
20	    private static async Task<(int EventId, int PriceCategoryId, int BookingId)> SeedGraphAsync(AppDbContext db, CancellationToken ct)
21	    {
22	        var @event = new Event { Titel = "Testkonzert", Beschreibung = "Beschreibung", Zeitpunkt = DateTime.UtcNow, DauerMinuten = 90, Altersfreigabe = 0 };
23	        var room = new Room { Name = "Saal 1", RowLabels = ["A"], ColumnCount = 5, Events = [@event] };
24	        var venue = new Venue { Name = "Testhalle", Rooms = [room] };
25	        var priceCategory = new PriceCategory { Name = "Standard", Preis = 10m };
26	        @event.PriceCategories.Add(priceCategory);
27	        var booking = new Booking { Reference = "ABCD2345", Name = "Erika Musterfrau", Email = "erika@example.com" };
28	
29	        db.Venues.Add(venue);
30	        db.Bookings.Add(booking);
31	        await db.SaveChangesAsync(ct);
32	
33	        return (@event.Id, priceCategory.Id, booking.Id);
34	    }
35	
36	    [Fact]
37	    public async Task BookingId_gesetzt_ohne_PriceCategoryId_verletzt_die_Check_Constraint()
38	    {
39	        var ct = TestContext.Current.CancellationToken;
40	        await using var db = _database.CreateContext();
41	        var (eventId, _, bookingId) = await SeedGraphAsync(db, ct);
42	
43	        db.BookingPositions.Add(new BookingPosition
44	        {
45	            EventId = eventId,
46	            RowLabel = "A",
47	            ColumnNumber = 1,
48	            BookingId = bookingId,
49	            PriceCategoryId = null,
50	        });
51	
52	        await Assert.ThrowsAsync<DbUpdateException>(() => db.SaveChangesAsync(ct));
53	    }
54	
55	    [Fact]
56	    public async Task PriceCategoryId_gesetzt_ohne_BookingId_verletzt_die_Check_Constraint()
57	    {
58	        var ct = TestContext.Current.CancellationToken;
59	        await using var db = _database.CreateContext();
60	        var (eventId, priceCategoryId, _) = await SeedGraphAsync(db, ct);
61	
62	        db.BookingPositions.Add(new BookingPosition
63	        {
64	            EventId = eventId,
65	            RowLabel = "A",
66	            ColumnNumber = 1,
67	            BookingId = null,
68	            PriceCategoryId = priceCategoryId,
69	        });
70	
71	        await Assert.ThrowsAsync<DbUpdateException>(() => db.SaveChangesAsync(ct));
72	    }
73	
74	    [Fact]
75	    public async Task BookingId_und_PriceCategoryId_gemeinsam_gesetzt_wird_gespeichert()
76	    {
77	        var ct = TestContext.Current.CancellationToken;
78	        await using var db = _database.CreateContext();
79	        var (eventId, priceCategoryId, bookingId) = await SeedGraphAsync(db, ct);
80	
81	        db.BookingPositions.Add(new BookingPosition
82	        {
83	            EventId = eventId,
84	            RowLabel = "A",
85	            ColumnNumber = 1,
86	            BookingId = bookingId,
87	            PriceCategoryId = priceCategoryId,
88	        });
89	        await db.SaveChangesAsync(ct);
90	
91	        var gespeichert = await db.BookingPositions.SingleAsync(
92	            bp => bp.EventId == eventId && bp.RowLabel == "A" && bp.ColumnNumber == 1, ct);
93	        Assert.Equal(bookingId, gespeichert.BookingId);
94	        Assert.Equal(priceCategoryId, gespeichert.PriceCategoryId);
95	    }
96	}
